// Gate and read-back heuristics over handler text.
//
// A gate is something that can stop the call before it runs: an Intentrax
// admission or execute call (SDK or a generated .intentrax/hooks/ entrypoint),
// or another approval step (Vercel AI SDK needsApproval, LangGraph interrupt,
// LangChain human-approval handlers, MCP elicitation, OpenAI Agents
// needs_approval). A read-back is a read of the affected state after the
// action. Both are recognized by name only, so both are heuristic.

import { allSideEffectsIn, sideEffectsIn } from "./classify.mjs";

// Generated by `npx @intentrax/sdk init <adapter>` (cli/intentrax.mjs ADAPTERS).
const INTENTRAX_HOOK_ENTRYPOINTS = [
  "beforeClaudeCodeToolUse", "beforeCursorShellExecution", "beforeMCPToolCall",
  "withIntentraxLangChainCallback", "withIntentraxLangGraphNode", "withIntentraxVercelAIRoute",
  "withIntentraxCustomAgentAdmission", "withIntentraxCrewAIStep", "withIntentraxAutoGenA2AWrapper",
  "withIntentraxOpenClawAgent", "withIntentraxN8NRequestNode", "withIntentraxDeepFlowStep",
];

const INTENTRAX_GATE = new RegExp(
  "\\b(?:admitAgentGatewayHttp|admitAgentGateway|admit_agent_gateway|executeIntentHttp|execute_intent|submit\\w*Admission|" +
    INTENTRAX_HOOK_ENTRYPOINTS.join("|") +
    "|withIntentrax\\w+)\\s*\\(",
);

// An approval flag counts only when it is not explicitly disabled:
// `needsApproval: false` / `needs_approval=False` / `requireApproval: null` are
// not gates.
const APPROVAL_GATE = /\bneedsApproval\s*:\s*(?:true\b|async\b|\(|(?!(?:false|null|undefined)\b)[A-Za-z_$])|\bneeds_approval\s*=\s*(?:True\b|(?!(?:False|None)\b)[A-Za-z_])|\brequires?_?[aA]pproval\b(?!\s*[:=]\s*(?:false|False|null|None|undefined|0)\b)|\bhuman_?[iI]n_?[tT]he_?[lL]oop|HumanInTheLoopMiddleware|HumanApprovalCallbackHandler|(?<![.\w$])interrupt\s*\(|\binterrupt_before\b|\binterruptBefore\b|\belicitInput\s*\(|\.elicit\s*\(|\bawait_?[aA]pproval\b|\brequest_?[aA]pproval\b|\bapproval_?[gG]ate\b/;

const READ_BACK_STRONG = /\bconfirmThenReport\b|\bconfirm_then_report\b|\bread_?[bB]ack\b|\breadback\b|\bwaitUntil\w+\s*\(|\bget_waiter\s*\(|\bverify(?:Effect|Deleted|Removed|After|State|Outcome|Result)\w*\s*\(|\bverify_(?:effect|deleted|removed|after|state|outcome|result)\w*\s*\(|\bconfirm(?:Deleted|Removed|State|Effect)\w*\s*\(|@intentrax\/sdk\/readback/;
const READ_AFTER = /\.(?:get|retrieve|describe\w*|head\w*|findUnique|findFirst|findOne|exists|fetch\w*|read\w*|list\w*)\s*\(|\bSELECT\s+[\w*]/i;

const SUCCESS_TEXT = /["'`][^"'`\n]{0,80}\b(?:deleted|removed|dropped|destroyed|refunded|sent|deployed|merged|transferred|charged|paid|succeeded|successfully|success|done|completed|created|updated)\b[^"'`\n]{0,80}["'`]|\b(?:success|ok|deleted|done)\s*[:=]\s*(?:true|True)\b|\bstatus\s*[:=]\s*["'](?:ok|success|succeeded|done|completed)["']/i;

function firstIndex(re, text) {
  const m = re.exec(text);
  return m ? m.index : -1;
}

// `spanText` is the tool's own handler text; `fileText` the whole file.
export function assessGate(spanText, fileText) {
  const effects = sideEffectsIn(spanText);
  const effectAt = effects.length ? Math.min(...effects.map((e) => e.index)) : -1;
  const reasons = [];

  const ix = firstIndex(INTENTRAX_GATE, spanText);
  if (ix >= 0) {
    if (effectAt >= 0 && ix > effectAt) {
      reasons.push("an Intentrax call appears after the side effect in the handler, so it does not gate it");
    } else {
      return { gated: true, kind: "intentrax", heuristic: true, reasons: ["handler calls an Intentrax admission/execute entrypoint before acting"] };
    }
  }
  const ax = firstIndex(APPROVAL_GATE, spanText);
  if (ax >= 0 && !(effectAt >= 0 && ax > effectAt)) {
    return { gated: true, kind: "approval", heuristic: true, reasons: ["handler has an approval step (needsApproval / interrupt / elicitation / human-in-the-loop)"] };
  }
  if (fileText && INTENTRAX_GATE.test(fileText) && ix < 0) {
    return { gated: true, kind: "intentrax", heuristic: true, reasons: ["an Intentrax admission/execute call is in the same file (assumed to be a shared dispatcher)"] };
  }
  if (fileText && APPROVAL_GATE.test(fileText) && ax < 0) {
    return { gated: true, kind: "approval", heuristic: true, reasons: ["an approval step is in the same file (assumed to cover this tool)"] };
  }
  return { gated: false, kind: null, heuristic: true, reasons };
}

export function assessReadBack(spanText) {
  if (READ_BACK_STRONG.test(spanText)) {
    return { present: true, heuristic: true, reasons: ["handler calls a read-back/confirmation step"], successMessage: SUCCESS_TEXT.test(spanText) };
  }
  // Every occurrence, so a repeated mutation after an earlier read is caught.
  const effects = allSideEffectsIn(spanText);
  if (effects.length) {
    const effectAt = effects[effects.length - 1].index;
    const after = spanText.slice(effectAt + 1);
    // Skip the effect's own call expression before looking for a read.
    const rest = after.slice(after.indexOf(")") + 1);
    if (READ_AFTER.test(rest)) {
      return { present: true, heuristic: true, reasons: ["handler reads state back after the side effect"], successMessage: SUCCESS_TEXT.test(spanText) };
    }
  }
  return { present: false, heuristic: true, reasons: ["no read of the affected state after the action"], successMessage: SUCCESS_TEXT.test(spanText) };
}

export function mentionsIntentraxGate(text) {
  return INTENTRAX_GATE.test(text);
}

export function hookCommandKind(command) {
  if (/intentrax/i.test(command)) return "intentrax";
  if (/approv|gate|guard|policy|confirm|deny|block|allowlist|permission/i.test(command)) return "approval";
  return null;
}
